<script setup>
import { onMounted, reactive } from 'vue';import { ElMessage } from 'element-plus';import { listDocuments,downloadDocument } from '../../api/document';import { saveDownload } from '../../utils/download';import { options,text,formatDate,tagType } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const state=reactive({list:[],total:0,pageNum:1,pageSize:10,documentType:'',reviewStatus:'',loading:false});const load=async()=>{state.loading=true;try{const r=await listDocuments({pageNum:state.pageNum,pageSize:state.pageSize,documentType:state.documentType||undefined,reviewStatus:state.reviewStatus||undefined});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};const download=async(row)=>{try{saveDownload(await downloadDocument(row.id),row.documentName)}catch(e){ElMessage.error(messageOf(e,'下载失败'))}};onMounted(load)
</script>
<template><div class="page"><PageHeader title="业务文件" description="查看本人承办案件的申请、答复和客户材料"/><div class="toolbar"><div class="filters"><el-select v-model="state.documentType" placeholder="文件类型" clearable @change="load"><el-option v-for="o in options('documentType')" :key="o.value" v-bind="o"/></el-select><el-select v-model="state.reviewStatus" placeholder="审核状态" clearable @change="load"><el-option v-for="o in options('reviewStatus')" :key="o.value" v-bind="o"/></el-select></div></div><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="documentName" label="文件名" min-width="230"/><el-table-column prop="caseId" label="案件 ID" width="90"/><el-table-column label="类型" width="140"><template #default="{row}">{{text('documentType',row.documentType)}}</template></el-table-column><el-table-column label="审核状态" width="120"><template #default="{row}"><el-tag :type="tagType(row.reviewStatus)">{{text('reviewStatus',row.reviewStatus)}}</el-tag></template></el-table-column><el-table-column label="上传时间" width="160"><template #default="{row}">{{formatDate(row.createTime)}}</template></el-table-column><el-table-column width="80"><template #default="{row}"><el-button link type="primary" @click="download(row)">下载</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/></div></template>
